{"command":"python3 -c '
s = "This is a very long line of text that exceeds eighty characters in total length and therefore should be wrapped by tex-fmt at an appropriate space or wrapping character."
words = s.split()
line = ""
for w in words:
    if len(line) + len(w) + (1 if line else 0) <= 80:
        line += (" " if line else "") + w
        print(f"Added {w}: line len = {len(line)}")
    else:
        print(f"OVERFLOW with {w}: line len would be {len(line) + 1 + len(w)}")
        break
'"}

