{"command":"cat <<'EOF' > src/logging.rs
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Verbosity {
    Off,
    Error,
    Warn,
    Info,
    Trace,
}

impl Verbosity {
    pub fn parse(s: &str) -> Self {
        match s.to_lowercase().as_str() {
            "off" => Verbosity::Off,
            "quiet" | "error" => Verbosity::Error,
            "warn" => Verbosity::Warn,
            "verbose" | "info" => Verbosity::Info,
            "trace" => Verbosity::Trace,
            _ => Verbosity::Warn,
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            Verbosity::Off => "off",
            Verbosity::Error => "error",
            Verbosity::Warn => "warn",
            Verbosity::Info => "info",
            Verbosity::Trace => "trace",
        }
    }
}

pub fn log_info(verbosity: Verbosity, file: &str, msg: &str) {
    if verbosity >= Verbosity::Info {
        eprintln!("INFO: tex-fmt {file}: {msg} ");
    }
}

pub fn log_warn_no_wrap(verbosity: Verbosity, file: &str, line_idx: usize, line_num: usize, content: &str) {
    if verbosity >= Verbosity::Warn {
        eprintln!("WARN: tex-fmt {file}: Line {line_idx} ({line_num}). Line cannot be wrapped. {content}");
    }
}

pub fn log_error(file: &str, msg: &str) {
    eprintln!("ERROR: tex-fmt {file}: {msg} ");
}

pub fn log_trace_read(verbosity: Verbosity, file: &str, bytes: usize) {
    if verbosity >= Verbosity::Trace {
        eprintln!("TRACE: tex-fmt {file}: Read {bytes} bytes. ");
    }
}

pub fn log_trace_line(
    verbosity: Verbosity,
    file: &str,
    line_idx: usize,
    line_num: usize,
    act: usize,
    vis: usize,
    content: &str,
) {
    if verbosity >= Verbosity::Trace {
        eprintln!("TRACE: tex-fmt {file}: Line {line_idx} ({line_num}). Indent: actual = {act}, visual = {vis}: {content}");
    }
}

pub fn log_trace_wrap(
    verbosity: Verbosity,
    file: &str,
    line_idx: usize,
    orig_line_num: usize,
    content: &str,
) {
    if verbosity >= Verbosity::Trace {
        eprintln!("TRACE: tex-fmt {file}: Line {line_idx} ({orig_line_num}). Wrapping long line. {content}");
    }
}
EOF"}

