                let arr = parse_string_array(val_str);
                let mut new_verbs = arr;
                let default_verbs = vec![
                    "verbatim".to_string(),
                    "Verbatim".to_string(),
                    "lstlisting".to_string(),
                    "minted".to_string(),
                    "comment".to_string(),
