        let mut s = line.trim();
        if s.is_empty() || s.starts_with('#') {
            continue;
        }

        // Handle trailing comment if not in quotes
        if let Some(idx) = s.find('#') {
            // simple check: if no quotes around #
            let prefix = &s[..idx];
            let quote_count = prefix.chars().filter(|&c| c == '"').count();
            if quote_count % 2 == 0 {
                s = prefix.trim();
            }
        }

        if s.is_empty() {
            continue;
        }

        if s.starts_with('[') && s.ends_with(']') && !s.contains('=') {
            // header line like [section], check if invalid syntax
            if s.contains(' ') {
                return Err(format!("thread 'main' panicked at src/config.rs:119:9:\nFailed to read config file at {}", path_display));
            }
            continue;
        }

        let parts: Vec<&str> = s.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(format!("Invalid TOML line: {}", s));
        }

        let key = parts[0].trim();
        let val_str = parts[1].trim();

        match key {
            "check" => {
                if let Ok(b) = val_str.parse::<bool>() {
                    config.check = b;
                }
            }
            "print" => {
                if let Ok(b) = val_str.parse::<bool>() {
                    config.print = b;
                }
            }
            "fail-on-change" | "fail_on_change" => {
                if let Ok(b) = val_str.parse::<bool>() {
                    config.fail_on_change = b;
                }
            }
            "wrap" => {
                if let Ok(b) = val_str.parse::<bool>() {
                    config.wrap = b;
                }
            }
            "wraplen" => {
                if let Ok(n) = val_str.parse::<usize>() {
                    config.wraplen = n;
                }
            }
            "wrapmin" => {
                if let Ok(n) = val_str.parse::<usize>() {
                    config.wrapmin = Some(n);
                }
            }
            "tabsize" => {
                if let Ok(n) = val_str.parse::<usize>() {
                    config.tabsize = n;
                }
            }
            "tabchar" => {
                let unquoted = strip_quotes(val_str);
                config.tabchar = unquoted.to_string();
            }
            "stdin" => {
                if let Ok(b) = val_str.parse::<bool>() {
                    config.stdin = b;
                }
            }
            "verbosity" => {
                let unquoted = strip_quotes(val_str);
                config.verbosity = Verbosity::parse(unquoted);
            }
            "lists" => {
                let arr = parse_string_array(val_str);
                let mut new_lists = arr;
                let default_lists = vec![
                    "itemize".to_string(),
                    "enumerate".to_string(),
                    "description".to_string(),
                    "inlineroman".to_string(),
                    "inventory".to_string(),
                ];
                for d in default_lists {
                    if !new_lists.contains(&d) {
                        new_lists.push(d);
                    }
                }
                config.lists = new_lists;
            }
            "verbatims" => {
                let arr = parse_string_array(val_str);
                let mut new_verbs = arr;
                let default_verbs = vec![
                    "verbatim".to_string(),
                    "Verbatim".to_string(),
                    "lstlisting".to_string(),
                    "minted".to_string(),
                    "comment".to_string(),
                ];
                for d in default_verbs {
                    if !new_verbs.contains(&d) {
                        new_verbs.push(d);
                    }
                }
                config.verbatims = new_verbs;
            }
            "no-indent-envs" | "no_indent_envs" => {
                let arr = parse_string_array(val_str);
                let mut new_no_indent = arr;
                let default_no_indent = vec!["document".to_string()];
                for d in default_no_indent {
                    if !new_no_indent.contains(&d) {
                        new_no_indent.push(d);
                    }
                }
                config.no_indent_envs = new_no_indent;
            }
            "wrap-chars" | "wrap_chars" => {
                let arr = parse_string_array(val_str);
                let mut new_chars = arr;
                if !new_chars.contains(&" ".to_string()) {
                    new_chars.push(" ".to_string());
                }
                config.wrap_chars = new_chars;
            }
            _ => {}
        }
    }

    Ok(())
}

fn strip_quotes(s: &str) -> &str {
    let t = s.trim();
    if (t.starts_with('"') && t.ends_with('"')) || (t.starts_with('\'') && t.ends_with('\'')) {
        if t.len() >= 2 {
            return &t[1..t.len() - 1];
        }
    }
    t
}

fn parse_string_array(s: &str) -> Vec<String> {
    let t = s.trim();
    if !t.starts_with('[') || !t.ends_with(']') {
        return Vec::new();
    }
    let inner = &t[1..t.len() - 1];
    let mut res = Vec::new();
    for item in inner.split(',') {
        let trimmed = item.trim();
        if !trimmed.is_empty() {
            res.push(strip_quotes(trimmed).to_string());
        }
    }
    res
}
EOF"}

