pub fn print_help() {
    let help_str = r#"tex-fmt 0.5.6

LaTeX formatter written in Rust

Usage: executable [OPTIONS] [files]...

Arguments:
  [files]...  List of files to be formatted

Options:
  -c, --check               Check formatting, do not modify files
  -p, --print               Print to stdout, do not modify files
  -f, --fail-on-change      Format files and return non-zero exit code if files are modified
  -n, --nowrap              Do not wrap long lines
  -l, --wraplen <N>         Line length for wrapping [default: 80]
  -t, --tabsize <N>         Number of characters to use as tab size [default: 2]
      --usetabs             Use tabs instead of spaces for indentation
  -s, --stdin               Process stdin as a single file, output to stdout
      --config <PATH>       Path to config file
      --noconfig            Do not read any config file
  -v, --verbose             Show info messages
  -q, --quiet               Hide warning messages
      --trace               Show trace messages
      --completion <SHELL>  Generate shell completion script [possible values: bash, elvish, fish, powershell, zsh]
      --man                 Generate man page
      --args                Print arguments passed to tex-fmt and exit
  -r, --recursive           Recursively search for files to format
  -h, --help                Print help
  -V, --version             Print version"#;
    println!("{}", help_str);
}

pub fn print_version() {
    println!("tex-fmt 0.5.6");
}

pub fn print_man() {
    print!("{}", MAN_PAGE);
}

pub fn print_completion(shell: &str) {
    match shell {
        "bash" => print!("{}", COMPLETION_BASH),
        "elvish" => print!("{}", COMPLETION_ELVISH),
        "fish" => print!("{}", COMPLETION_FISH),
        "powershell" => print!("{}", COMPLETION_POWERSHELL),
        "zsh" => print!("{}", COMPLETION_ZSH),
        _ => {}
    }
}

pub fn print_args(config: &Config, resolved_files: &[String]) {
    println!("tex-fmt");
    println!("  check:                   {}", config.check);
    println!("  print:                   {}", config.print);
    println!("  fail-on-change:          {}", config.fail_on_change);
    println!("  wrap:                    {}", config.wrap);
    println!("  wraplen:                 {}", config.wraplen);
    println!("  wrapmin:                 {}", config.get_wrapmin());
    println!("  tabsize:                 {}", config.tabsize);
    println!("  tabchar:                 {}", config.tabchar);
    println!("  stdin:                   {}", config.stdin);
    println!("  config:                  {}", config.config.as_deref().unwrap_or("None"));
    println!("  verbosity:               {}", config.verbosity.as_str());

    print_list_arg("lists", &config.lists);
    print_list_arg("verbatims", &config.verbatims);
    print_list_arg("no-indent-envs", &config.no_indent_envs);
    print_list_arg("wrap-chars", &config.wrap_chars);

    if !resolved_files.is_empty() {
        print_list_arg("files", resolved_files);
    }
}

fn print_list_arg(key: &str, items: &[String]) {
    if items.is_empty() {
        let prefix = format!("  {}:", key);
        println!("{:27}", prefix);
        return;
    }

    for (idx, item) in items.iter().enumerate() {
        if idx == 0 {
            let prefix = format!("  {}:", key);
            println!("{:27}{}", prefix, item);
        } else {
            println!("{:27}{}", "", item);
        }
    }
}
EOF"}

