{"command":"cat <<'EOF' > src/format.rs
use crate::config::Config;
use crate::logging::*;

pub fn process_file(
    content: &str,
    config: &Config,
    file_name: &str,
) -> String {
    let raw_lines = split_raw_lines(content);

    // Step 1: Pre-process line splitting for tokens preceded by non-whitespace
    let split_lines = perform_line_splitting(&raw_lines, &config.verbatims);

    // Step 2: Collapse blank lines & trim trailing spaces
    let collapsed = collapse_blank_lines(&split_lines);

    // Step 3: Format lines (indentation and wrapping)
    format_lines(&collapsed, config, file_name)
}

fn split_raw_lines(content: &str) -> Vec<String> {
    content
        .lines()
        .map(|l| {
            if l.ends_with('\r') {
                l[..l.len() - 1].to_string()
            } else {
                l.to_string()
            }
        })
        .collect()
}

fn perform_line_splitting(lines: &[String], verbatims: &[String]) -> Vec<String> {
    let mut res = Vec::new();
    let mut in_verb: Option<String> = None;
    let mut off = false;

    for line in lines {
        if line.contains("% tex-fmt: off") {
            off = true;
            res.push(line.clone());
            continue;
        }
        if line.contains("% tex-fmt: on") {
            off = false;
            res.push(line.clone());
            continue;
        }
        if off || line.contains("% tex-fmt: skip") {
            res.push(line.clone());
            continue;
        }

        if let Some(ref env) = in_verb {
            if line.contains(&format!("\\end{{{}}}", env)) {
                in_verb = None;
            }
            res.push(line.clone());
            continue;
        }

        let mut started_verb = false;
        for v in verbatims {
            if line.contains(&format!("\\begin{{{}}}", v)) {
                in_verb = Some(v.clone());
                started_verb = true;
                break;
            }
        }
        if started_verb {
            res.push(line.clone());
            continue;
        }

        // Split line if needed
        let sub_split = split_single_line(line);
        res.extend(sub_split);
    }

    res
}

fn split_single_line(line: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut cur = line;

    loop {
        let mut earliest_split: Option<(usize, usize)> = None; // (byte_idx, match_len)

        // Find earliest occurrence of split triggers preceded by non-whitespace
        find_trigger(cur, "\\begin{", &mut earliest_split);
        find_trigger(cur, "\\end{", &mut earliest_split);
        find_trigger(cur, "\\item", &mut earliest_split);

        find_trigger(cur, "\\part{", &mut earliest_split);
        find_trigger(cur, "\\part*{", &mut earliest_split);
        find_trigger(cur, "\\chapter{", &mut earliest_split);
        find_trigger(cur, "\\chapter*{", &mut earliest_split);
        find_trigger(cur, "\\section{", &mut earliest_split);
        find_trigger(cur, "\\section*{", &mut earliest_split);
        find_trigger(cur, "\\subsection{", &mut earliest_split);
        find_trigger(cur, "\\subsection*{", &mut earliest_split);
        find_trigger(cur, "\\subsubsection{", &mut earliest_split);
        find_trigger(cur, "\\subsubsection*{", &mut earliest_split);

        if let Some((idx, _len)) = earliest_split {
            let left = &cur[..idx];
            let right = &cur[idx..];

            if !left.trim().is_empty() {
                result.push(left.trim_end().to_string());
                cur = right.trim_start();
            } else {
                // If preceded only by whitespace, move past this trigger to find next
                let next_idx = idx + 1;
                if next_idx < cur.len() {
                    // search remainder
                    let mut remainder_split = None;
                    find_trigger(&cur[next_idx..], "\\begin{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\end{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\item", &mut remainder_split);

                    find_trigger(&cur[next_idx..], "\\part{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\part*{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\chapter{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\chapter*{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\section{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\section*{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\subsection{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\subsection*{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\subsubsection{", &mut remainder_split);
                    find_trigger(&cur[next_idx..], "\\subsubsection*{", &mut remainder_split);

                    if let Some((r_idx, _)) = remainder_split {
                        let actual_idx = next_idx + r_idx;
                        let left = &cur[..actual_idx];
                        let right = &cur[actual_idx..];
                        result.push(left.trim_end().to_string());
                        cur = right.trim_start();
                    } else {
                        result.push(cur.to_string());
                        break;
                    }
                } else {
                    result.push(cur.to_string());
                    break;
                }
            }
        } else {
            result.push(cur.to_string());
            break;
        }
    }

    result
}

fn find_trigger(s: &str, pat: &str, earliest: &mut Option<(usize, usize)>) {
    let mut search_from = 0;
    while let Some(idx) = s[search_from..].find(pat) {
        let abs_idx = search_from + idx;
        let prefix = &s[..abs_idx];
        if !prefix.trim().is_empty() {
            if earliest.is_none() || abs_idx < earliest.unwrap().0 {
                *earliest = Some((abs_idx, pat.len()));
            }
            break;
        } else {
            search_from = abs_idx + pat.len();
        }
    }
}

fn collapse_blank_lines(lines: &[String]) -> Vec<String> {
    let mut res = Vec::new();
    let mut blank_count = 0;

    for line in lines {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            blank_count += 1;
        } else {
            if blank_count > 0 {
                res.push(String::new());
                blank_count = 0;
            }
            res.push(line.trim_end().to_string());
        }
    }

    res
}

fn format_lines(lines: &[String], config: &Config, file_name: &str) -> String {
    let mut actual_indent: usize = 0;
    let mut in_verb: Option<String> = None;
    let mut off = false;
    let mut output_lines: Vec<String> = Vec::new();

    let wrapmin = config.get_wrapmin();

    for (line_idx, line) in lines.iter().enumerate() {
        let orig_line_num = line_idx + 1;

        if line.contains("% tex-fmt: off") {
            off = true;
            output_lines.push(line.clone());
            continue;
        }
        if line.contains("% tex-fmt: on") {
            off = false;
            output_lines.push(line.clone());
            continue;
        }
        if off || line.contains("% tex-fmt: skip") {
            output_lines.push(line.clone());
            continue;
        }

        if let Some(ref env) = in_verb {
            if line.contains(&format!("\\end{{{}}}", env)) {
                in_verb = None;
            }
            output_lines.push(line.clone());
            continue;
        }

        let mut started_verb = false;
        for v in &config.verbatims {
            if line.contains(&format!("\\begin{{{}}}", v)) {
                in_verb = Some(v.clone());
                started_verb = true;
                break;
            }
        }
        if started_verb {
            output_lines.push(line.clone());
            continue;
        }

        let trimmed = line.trim();
        if trimmed.is_empty() {
            output_lines.push(String::new());
            continue;
        }

        // Calculate visual_indent and update actual_indent
        let mut visual_indent = actual_indent;

        // Check if line closes an environment or decreases indent
        let is_end_env = get_end_env(trimmed);
        if let Some(ref env) = is_end_env {
            if !config.no_indent_envs.contains(env) {
                if config.lists.contains(env) {
                    actual_indent = actual_indent.saturating_sub(2);
                } else {
                    actual_indent = actual_indent.saturating_sub(1);
                }
            }
            visual_indent = actual_indent;
        } else if trimmed.starts_with("\\item") {
            visual_indent = actual_indent.saturating_sub(1);
        } else if trimmed.starts_with("\\]") || trimmed.starts_with("\\)") {
            actual_indent = actual_indent.saturating_sub(1);
            visual_indent = actual_indent;
        } else if trimmed.starts_with('}') {
            actual_indent = actual_indent.saturating_sub(1);
            visual_indent = actual_indent;
        }

