        let prefix = &s[..abs_idx];
        if !prefix.trim().is_empty() {
            if earliest.is_none() || abs_idx < earliest.unwrap().0 {
                *earliest = Some((abs_idx, pat.len()));
            }
            break;
        } else {
            search_from = abs_idx + pat.len();
        }
    }
}

fn collapse_blank_lines(lines: &[String]) -> Vec<String> {
    let mut res = Vec::new();
    let mut blank_count = 0;

    for line in lines {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            blank_count += 1;
        } else {
            if blank_count > 0 {
                res.push(String::new());
                blank_count = 0;
            }
            res.push(line.trim_end().to_string());
        }
    }

    res
}

fn format_lines(lines: &[String], config: &Config, file_name: &str) -> String {
    let mut actual_indent: usize = 0;
    let mut in_verb: Option<String> = None;
    let mut off = false;
    let mut output_lines: Vec<String> = Vec::new();

    let wrapmin = config.get_wrapmin();

    for (line_idx, line) in lines.iter().enumerate() {
        let orig_line_num = line_idx + 1;

        if line.contains("% tex-fmt: off") {
            off = true;
            output_lines.push(line.clone());
            continue;
        }
        if line.contains("% tex-fmt: on") {
            off = false;
            output_lines.push(line.clone());
            continue;
        }
        if off || line.contains("% tex-fmt: skip") {
            output_lines.push(line.clone());
            continue;
        }

        if let Some(ref env) = in_verb {
            if line.contains(&format!("\\end{{{}}}", env)) {
                in_verb = None;
            }
            output_lines.push(line.clone());
            continue;
        }

        let mut started_verb = false;
        for v in &config.verbatims {
            if line.contains(&format!("\\begin{{{}}}", v)) {
                in_verb = Some(v.clone());
                started_verb = true;
                break;
            }
        }
        if started_verb {
            output_lines.push(line.clone());
            continue;
        }

        let trimmed = line.trim();
        if trimmed.is_empty() {
            output_lines.push(String::new());
            continue;
        }

        // Calculate visual_indent and update actual_indent
        let mut visual_indent = actual_indent;

        // Check if line closes an environment or decreases indent
        let is_end_env = get_end_env(trimmed);
        if let Some(ref env) = is_end_env {
            if !config.no_indent_envs.contains(env) {
                if config.lists.contains(env) {
                    actual_indent = actual_indent.saturating_sub(2);
                } else {
                    actual_indent = actual_indent.saturating_sub(1);
                }
            }
            visual_indent = actual_indent;
        } else if trimmed.starts_with("\\item") {
            visual_indent = actual_indent.saturating_sub(1);
        } else if trimmed.starts_with("\\]") || trimmed.starts_with("\\)") {
            actual_indent = actual_indent.saturating_sub(1);
            visual_indent = actual_indent;
        } else if trimmed.starts_with('}') {
            actual_indent = actual_indent.saturating_sub(1);
            visual_indent = actual_indent;
        }

        // Check if line opens an environment or increases indent
        let is_begin_env = get_begin_env(trimmed);
        if let Some(ref env) = is_begin_env {
            if !config.no_indent_envs.contains(env) {
                if config.lists.contains(env) {
                    actual_indent += 2;
                } else {
                    actual_indent += 1;
                }
            }
        } else if (trimmed.ends_with("\\[") || trimmed.ends_with("\\(")) && !has_matching_close_math(trimmed) {
            actual_indent += 1;
        } else if trimmed.starts_with('@') && trimmed.contains('{') && !trimmed.contains('}') {
            actual_indent += 1;
        }

        log_trace_line(
            config.verbosity,
            file_name,
            line_idx + 1,
            orig_line_num,
            actual_indent,
            visual_indent,
            trimmed,
        );

        let indent_str = if config.tabchar == "tab" {
            "\t".repeat(visual_indent)
        } else {
            " ".repeat(visual_indent * config.tabsize)
        };

        let formatted_line = format!("{}{}", indent_str, trimmed);

        if config.wrap && formatted_line.chars().count() > config.wraplen {
            let wrapped_sub_lines = wrap_line(
                &formatted_line,
                &indent_str,
                config.wraplen,
                wrapmin,
                &config.wrap_chars,
                file_name,
                line_idx,
                orig_line_num,
                config.verbosity,
            );
            output_lines.extend(wrapped_sub_lines);
        } else {
            output_lines.push(formatted_line);
        }
    }

    if output_lines.is_empty() {
        "\n".to_string()
    } else {
        let mut res = output_lines.join("\n");
        res.push('\n');
        res
    }
}

fn get_begin_env(s: &str) -> Option<String> {
    if let Some(idx) = s.find("\\begin{") {
        let start = idx + 7;
        if let Some(end) = s[start..].find('}') {
            return Some(s[start..start + end].to_string());
        }
    }
    None
}

fn get_end_env(s: &str) -> Option<String> {
    if let Some(idx) = s.find("\\end{") {
        let start = idx + 5;
        if let Some(end) = s[start..].find('}') {
            return Some(s[start..start + end].to_string());
        }
    }
    None
}

fn has_matching_close_math(s: &str) -> bool {
    (s.contains("\\[") && s.contains("\\]")) || (s.contains("\\(") && s.contains("\\)"))
}

fn wrap_line(
    line: &str,
    indent_str: &str,
    wraplen: usize,
    wrapmin: usize,
    wrap_chars: &[String],
    file_name: &str,
    line_idx: usize,
    orig_line_num: usize,
    verbosity: Verbosity,
) -> Vec<String> {
    if line.chars().count() <= wraplen {
        return vec![line.to_string()];
    }

    let mut result = Vec::new();
    let mut current = line.to_string();

    while current.chars().count() > wraplen {
        log_trace_wrap(verbosity, file_name, line_idx + 1, orig_line_num, &current);

        let cur_chars: Vec<char> = current.chars().collect();
        let mut prev_wrap_idx = None;
        let mut chosen_wrap_idx = None;

        for (idx, &ch) in cur_chars.iter().enumerate() {
            let total_len = idx + 1;
            let ch_str = ch.to_string();

            if wrap_chars.contains(&ch_str) {
                if total_len > wraplen {
                    if let Some(p) = prev_wrap_idx {
                        chosen_wrap_idx = Some(p);
                    } else {
                        chosen_wrap_idx = Some(idx);
                    }
                    break;
                } else if total_len >= wrapmin {
                    if let Some(p) = prev_wrap_idx {
                        chosen_wrap_idx = Some(p);
                    } else {
                        chosen_wrap_idx = Some(idx);
                    }
                    break;
                } else {
                    prev_wrap_idx = Some(idx);
                }
            }
        }

        if chosen_wrap_idx.is_none() {
            // Check if overflow happened past wraplen without reaching wrapmin
            if let Some(p) = prev_wrap_idx {
                chosen_wrap_idx = Some(p);
            }
        }

        if let Some(wrap_idx) = chosen_wrap_idx {
            let wrap_ch = cur_chars[wrap_idx];
            let part1: String = if wrap_ch == ' ' {
                cur_chars[..wrap_idx].iter().collect()
            } else {
                cur_chars[..=wrap_idx].iter().collect()
            };

            let mut remainder_chars = &cur_chars[wrap_idx + 1..];
            while let Some(&' ') = remainder_chars.first() {
                remainder_chars = &remainder_chars[1..];
            }
            let part2_content: String = remainder_chars.iter().collect();

            result.push(part1.trim_end().to_string());

            let is_comment = current.trim_start().starts_with('%');
            let mut part2 = String::new();
            part2.push_str(indent_str);
            if is_comment {
                part2.push_str("% ");
            }
            part2.push_str(&part2_content);

            current = part2;
        } else {
            log_warn_no_wrap(verbosity, file_name, line_idx + 1, orig_line_num, &current);
            result.push(current);
            return result;
        }
    }

    result.push(current);
    result
}
EOF"}

