use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::process;

use cli::*;
use config::Config;
use logging::*;

fn main() {
    let cli_args = parse_cli();

    if cli_args.help {
        print_help();
        process::exit(0);
    }

    if cli_args.version {
        print_version();
        process::exit(0);
    }

    if cli_args.man {
        print_man();
        process::exit(0);
    }

    if let Some(ref sh) = cli_args.completion {
        print_completion(sh);
        process::exit(0);
    }

    // Load config
    let mut config = Config::load(cli_args.config_path.as_deref(), cli_args.noconfig);

    // Override config with CLI flags
    if cli_args.check {
        config.check = true;
    }
    if cli_args.print {
        config.print = true;
    }
    if cli_args.fail_on_change {
        config.fail_on_change = true;
    }
    if cli_args.nowrap {
        config.wrap = false;
    }
    if let Some(wl) = cli_args.wraplen {
        config.wraplen = wl;
    }
    if let Some(ts) = cli_args.tabsize {
        config.tabsize = ts;
    }
    if cli_args.usetabs {
        config.tabchar = "tab".to_string();
    }
    if cli_args.stdin {
        config.stdin = true;
    }
    if cli_args.verbose {
        config.verbosity = Verbosity::Info;
    }
    if cli_args.quiet {
        config.verbosity = Verbosity::Error;
    }
    if cli_args.trace {
        config.verbosity = Verbosity::Trace;
    }

    if cli_args.args_flag {
        let resolved_files = resolve_files_for_args(&cli_args.files);
        print_args(&config, &resolved_files);
        process::exit(0);
    }

    // Handle --stdin
    if config.stdin {
        if !cli_args.files.is_empty() {
            log_error("", "Do not provide file name(s) when using --stdin.");
            process::exit(1);
        }

        let mut input = String::new();
        if io::stdin().read_to_string(&mut input).is_err() {
            log_error("<stdin>", "Could not open file.");
            process::exit(1);
        }

        log_trace_read(config.verbosity, "<stdin>", input.as_bytes().len());
        log_info(config.verbosity, "<stdin>", "Formatting started.");
        let formatted = format::process_file(&input, &config, "<stdin>");
        log_info(config.verbosity, "<stdin>", "Formatting complete.");

        print!("{}", formatted);
        process::exit(0);
    }

    // File processing
    let raw_inputs = if cli_args.files.is_empty() {
        if cli_args.recursive {
            vec![".".to_string()]
        } else {
            log_error("", "No files specified. Provide filenames, or pass --recursive or --stdin.");
            process::exit(1);
        }
    } else {
        cli_args.files.clone()
    };

    let mut target_files = Vec::new();

    for raw in &raw_inputs {
        let path = Path::new(raw);
        if path.is_dir() {
            if !cli_args.recursive {
                log_error("", "A directory was passed without --recursive.");
                process::exit(1);
            }
            let found = find_files_recursive(path);
            target_files.extend(found);
        } else {
            if path.exists() {
                target_files.push(raw.clone());
            } else {
                let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
                if matches!(ext, "tex" | "bib" | "cls" | "sty") {
                    target_files.push(raw.clone());
                } else if ext.is_empty() {
                    target_files.push(format!("{}.tex", raw));
                } else {
                    log_error(raw, "File type invalid.");
                    process::exit(1);
                }
            }
        }
    }

    if target_files.is_empty() {
        log_error("", "No files specified. Provide filenames, or pass --recursive or --stdin.");
        process::exit(1);
    }

    let mut any_error = false;
    let mut any_modified = false;

    for file_path in &target_files {
        let content = match fs::read_to_string(file_path) {
            Ok(c) => c,
            Err(_) => {
                log_error(file_path, "Could not open file.");
                any_error = true;
                continue;
            }
        };

        log_info(config.verbosity, file_path, "Formatting started.");
        let formatted = format::process_file(&content, &config, file_path);
        log_info(config.verbosity, file_path, "Formatting complete.");

        let is_different = formatted != content;

        if is_different {
            any_modified = true;
            if config.check {
                log_error(file_path, "Incorrect formatting.");
                any_error = true;
            } else if config.print {
                print!("{}", formatted);
            } else {
                if let Err(_) = fs::write(file_path, &formatted) {
                    panic!("Could not write the file");
                }
            }
        } else {
            if config.print {
                print!("{}", content);
            }
        }
    }

    if any_error || (config.fail_on_change && any_modified) {
        process::exit(1);
    } else {
        process::exit(0);
    }
}

fn resolve_files_for_args(files: &[String]) -> Vec<String> {
    let mut res = Vec::new();
    for f in files {
        let path = Path::new(f);
        if path.is_dir() || path.exists() {
            res.push(f.clone());
        } else {
            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
            if ext.is_empty() {
                res.push(format!("{}.tex", f));
            } else {
                res.push(f.clone());
            }
        }
    }
    res
}

fn find_files_recursive(dir: &Path) -> Vec<String> {
    let mut res = Vec::new();
    let ignore_patterns = load_ignore_patterns(dir);

    fn walk(
        current_dir: &Path,
        base_dir: &Path,
        ignore_patterns: &[String],
        res: &mut Vec<String>,
    ) {
        let entries = match fs::read_dir(current_dir) {
            Ok(e) => e,
            Err(_) => return,
        };

        for entry in entries.flatten() {
            let path = entry.path();
            let name = match path.file_name().and_then(|n| n.to_str()) {
                Some(n) => n,
                None => continue,
            };

            // Skip hidden files/dirs starting with .
            if name.starts_with('.') {
                continue;
            }

            // Check gitignore / ignore patterns
            if is_ignored(name, &path, ignore_patterns) {
                continue;
            }

            if path.is_dir() {
                walk(&path, base_dir, ignore_patterns, res);
            } else if path.is_file() {
                let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
                if matches!(ext, "tex" | "bib" | "cls" | "sty") {
                    res.push(path.to_string_lossy().to_string());
                }
            }
        }
    }

    walk(dir, dir, &ignore_patterns, &mut res);
    res.sort();
    res
}

fn load_ignore_patterns(dir: &Path) -> Vec<String> {
    let mut patterns = Vec::new();
    for fname in &[".gitignore", ".ignore"] {
        let p = dir.join(fname);
        if p.is_file() {
            if let Ok(c) = fs::read_to_string(&p) {
                for line in c.lines() {
                    let s = line.trim();
                    if !s.is_empty() && !s.starts_with('#') {
                        patterns.push(s.to_string());
                    }
                }
            }
        }
    }
    patterns
}

fn is_ignored(name: &str, path: &Path, patterns: &[String]) -> bool {
    let path_str = path.to_string_lossy();
    for pat in patterns {
        let clean_pat = pat.trim_end_matches('/');
        if name == clean_pat || path_str.ends_with(clean_pat) {
            return true;
        }
        if clean_pat.starts_with('*') {
            let suffix = &clean_pat[1..];
            if name.ends_with(suffix) {
                return true;
            }
        }
    }
    false
}
EOF"}

