fn resolve_files_for_args(files: &[String]) -> Vec<String> {
    let mut res = Vec::new();
    for f in files {
        let path = Path::new(f);
        if path.is_dir() || path.exists() {
            res.push(f.clone());
        } else {
            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
            if ext.is_empty() {
                res.push(format!("{}.tex", f));
            } else {
                res.push(f.clone());
            }
        }
    }
    res
}

fn find_files_recursive(dir: &Path) -> Vec<String> {
    let mut res = Vec::new();
    let ignore_patterns = load_ignore_patterns(dir);

    fn walk(
        current_dir: &Path,
        base_dir: &Path,
        ignore_patterns: &[String],
        res: &mut Vec<String>,
    ) {
        let entries = match fs::read_dir(current_dir) {
            Ok(e) => e,
            Err(_) => return,
        };

        for entry in entries.flatten() {
            let path = entry.path();
            let name = match path.file_name().and_then(|n| n.to_str()) {
                Some(n) => n,
                None => continue,
            };

            // Skip hidden files/dirs starting with .
            if name.starts_with('.') {
                continue;
            }

            // Check gitignore / ignore patterns
            if is_ignored(name, &path, ignore_patterns) {
                continue;
            }

            if path.is_dir() {
                walk(&path, base_dir, ignore_patterns, res);
            } else if path.is_file() {
                let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
                if matches!(ext, "tex" | "bib" | "cls" | "sty") {
                    res.push(path.to_string_lossy().to_string());
                }
            }
        }
    }

    walk(dir, dir, &ignore_patterns, &mut res);
    res.sort();
    res
}

fn load_ignore_patterns(dir: &Path) -> Vec<String> {
    let mut patterns = Vec::new();
    for fname in &[".gitignore", ".ignore"] {
        let p = dir.join(fname);
        if p.is_file() {
            if let Ok(c) = fs::read_to_string(&p) {
                for line in c.lines() {
                    let s = line.trim();
                    if !s.is_empty() && !s.starts_with('#') {
                        patterns.push(s.to_string());
                    }
                }
            }
        }
    }
    patterns
}

